create or replace function public.business_invite_member(p_business_id uuid,p_user_id uuid,p_role public.business_member_role default 'staff') returns public.business_members language plpgsql security invoker set search_path=public as $$ declare v public.business_members; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if p_role='owner' then raise exception 'Owner role requires ownership transfer'; end if; if not exists(select 1 from public.business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and bm.role='owner') and not exists(select 1 from public.profiles pr where pr.id=auth.uid() and pr.is_admin=true) then raise exception 'Only the business owner can manage members'; end if; if exists(select 1 from public.business_members where business_id=p_business_id and user_id=p_user_id) then raise exception 'User is already a member'; end if; insert into public.business_members(business_id,user_id,role) values(p_business_id,p_user_id,p_role) returning * into v; return v; end; $$; revoke execute on function public.business_invite_member(uuid,uuid,public.business_member_role) from public; grant execute on function public.business_invite_member(uuid,uuid,public.business_member_role) to authenticated;
create or replace function public.business_change_member_role(p_business_id uuid,p_user_id uuid,p_role public.business_member_role) returns public.business_members language plpgsql security invoker set search_path=public as $$ declare v public.business_members; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if p_role='owner' then raise exception 'Owner role requires ownership transfer'; end if; if not exists(select 1 from public.business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and bm.role='owner') and not exists(select 1 from public.profiles pr where pr.id=auth.uid() and pr.is_admin=true) then raise exception 'Only the business owner can manage member roles'; end if; update public.business_members set role=p_role where business_id=p_business_id and user_id=p_user_id returning * into v; if not found then raise exception 'Member not found'; end if; return v; end; $$; revoke execute on function public.business_change_member_role(uuid,uuid,public.business_member_role) from public; grant execute on function public.business_change_member_role(uuid,uuid,public.business_member_role) to authenticated;
create or replace function public.business_remove_member(p_business_id uuid,p_user_id uuid) returns boolean language plpgsql security invoker set search_path=public as $$ begin if auth.uid() is null then raise exception 'Authentication required'; end if; if not exists(select 1 from public.business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and bm.role='owner') and not exists(select 1 from public.profiles pr where pr.id=auth.uid() and pr.is_admin=true) then raise exception 'Only the business owner can remove members'; end if; if exists(select 1 from public.business_members where business_id=p_business_id and user_id=p_user_id and role='owner') then raise exception 'Ownership must be transferred before removing the owner'; end if; delete from public.business_members where business_id=p_business_id and user_id=p_user_id; return found; end; $$; revoke execute on function public.business_remove_member(uuid,uuid) from public; grant execute on function public.business_remove_member(uuid,uuid) to authenticated;
create or replace function public.business_transfer_ownership(p_business_id uuid,p_new_owner_id uuid) returns public.business_members language plpgsql security invoker set search_path=public as $$ declare v public.business_members; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if not exists(select 1 from public.business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and bm.role='owner') then raise exception 'Only the current owner can transfer ownership'; end if; if p_new_owner_id=auth.uid() then raise exception 'New owner must be a different user'; end if; if not exists(select 1 from public.business_members where business_id=p_business_id and user_id=p_new_owner_id) then raise exception 'New owner must already be a business member'; end if; update public.business_members set role='admin' where business_id=p_business_id and user_id=auth.uid(); update public.business_members set role='owner' where business_id=p_business_id and user_id=p_new_owner_id returning * into v; return v; end; $$; revoke execute on function public.business_transfer_ownership(uuid,uuid) from public; grant execute on function public.business_transfer_ownership(uuid,uuid) to authenticated;
